/**
 * Parameter Types
 *
 * Types related to plugin parameters.
 */

import { IpcEvents, IpcMethods } from '../ipc/constants';

export type ParameterType = 'float' | 'bool' | 'enum';
export type ParameterValue = number | boolean | string;
export type ParameterVariant = string | undefined;

/**
 * Augmentable parameter ID registry.
 *
 * The generated `ui/src/generated/parameters.ts` file augments the global
 * `WavecraftParameterIdMap` interface with the plugin's concrete parameter IDs.
 */
declare global {
  // eslint-disable-next-line @typescript-eslint/no-empty-object-type
  interface WavecraftParameterIdMap {}
}

// eslint-disable-next-line @typescript-eslint/no-empty-object-type
export interface ParameterIdMap extends WavecraftParameterIdMap {}

type ParameterIdMapEntryValue = true | number | boolean;

type ParameterIdMapEntry<TId extends ParameterId> = TId extends keyof ParameterIdMap
  ? ParameterIdMap[TId]
  : true;

/**
 * Compile-time parameter value type for a specific parameter ID.
 *
 * Generated `ParameterIdMap` augmentation can provide value types per ID:
 * - `number` for float/enum-like params
 * - `boolean` for bool params
 *
 * Legacy generated maps that use `true` keep resolving to `number`.
 */
export type ParameterValueForId<TId extends ParameterId> =
  ParameterIdMapEntry<TId> extends true
    ? number
    : ParameterIdMapEntry<TId> extends ParameterIdMapEntryValue
      ? ParameterIdMapEntry<TId>
      : number;

/**
 * Internal marker key added by generated type augmentation.
 *
 * Used to distinguish generated entries from concrete parameter IDs.
 */
export type ParameterIdMapAugmentedMarker = '__wavecraft_internal_augmented__';

/**
 * Type-safe parameter identifier.
 *
 * Resolves to a literal string union of plugin parameter IDs derived from the
 * generated augmentation map. When no IDs are generated, this resolves to
 * `never`.
 */
export type ParameterId = Exclude<
  Extract<keyof ParameterIdMap, string>,
  ParameterIdMapAugmentedMarker
>;

export interface ParameterInfo<
  T extends ParameterValue = ParameterValue,
  V extends ParameterVariant = ParameterVariant,
> {
  id: ParameterId;
  name: string;
  type: ParameterType;
  value: T;
  default: T;
  min: number;
  max: number;
  unit?: string;
  group?: string;
  /** Variant labels for enum parameters (e.g., ["Sine", "Square", "Saw", "Triangle"]). */
  variants?: V[];
}

// getParameter
export interface GetParameterParams {
  id: ParameterId;
}

export interface GetParameterResult {
  id: ParameterId;
  value: ParameterValue;
}

// setParameter
export interface SetParameterParams {
  id: ParameterId;
  value: ParameterValue;
}

export type SetParameterResult = Record<string, never>;

// getAllParameters
export interface GetAllParametersResult<
  T extends ParameterValue = ParameterValue,
  V extends ParameterVariant = ParameterVariant,
> {
  parameters: ParameterInfo<T, V>[];
}

// Notification: parameterChanged
export interface ParameterChangedNotification {
  id: ParameterId;
  value: ParameterValue;
}

// Method Names (matching Rust constants)
export const METHOD_GET_PARAMETER = IpcMethods.GET_PARAMETER;
export const METHOD_SET_PARAMETER = IpcMethods.SET_PARAMETER;
export const METHOD_GET_ALL_PARAMETERS = IpcMethods.GET_ALL_PARAMETERS;
export const NOTIFICATION_PARAMETER_CHANGED = IpcEvents.PARAMETER_CHANGED;
